$(".news_intro_carousel_title[index='0']").addClass("show-text")
$(function () {
  updateTraffic()
  if (localStorage.getItem("mainSearchTitle")) {
    localStorage.removeItem("mainSearchTitle");
  }
  $("#searchInput").val("")

  // 获取元素
  const clickArea = $('#approval-click-area');
  const submenu = $('#approval-submenu');
  const container = $('.drug-registration-hover');

  // 点击显示/隐藏下拉菜单
  clickArea.on('click', function (e) {
    e.stopPropagation(); // 阻止事件冒泡
    submenu.toggleClass('show');
  });

  // 鼠标离开容器时隐藏菜单
  container.on('mouseleave', function () {
    submenu.removeClass('show');
  });

  // 点击页面其他区域隐藏菜单
  $(document).on('click', function () {
    submenu.removeClass('show');
  });

  // 防止下拉菜单内部点击导致菜单关闭
  submenu.on('click', function (e) {
    e.stopPropagation();
  });
})
